function minCostToEqualizeArray(nums, cost1, cost2) {
  const MOD = 1000000007;
  const n = nums.length;
  let high = 0;
  let low = Infinity;
  let sum = 0;
  for (const value of nums) {
    high = Math.max(high, value);
    low = Math.min(low, value);
    sum += value;
  }
  if (n <= 2 || 2 * cost1 <= cost2) {
    return ((n * high - sum) % MOD) * cost1 % MOD;
  }
  let best = Infinity;
  for (let target = high; target <= 2 * high; target++) {
    const total = n * target - sum;
    const largest = target - low;
    let cost;
    if (2 * largest <= total) {
      cost = Math.floor(total / 2) * cost2 + (total % 2) * cost1;
    } else {
      const pairs = total - largest;
      cost = pairs * cost2 + (largest - pairs) * cost1;
    }
    best = Math.min(best, cost);
  }
  return best % MOD;
}

