function minCostToEqualizeArray(nums, cost1, cost2) {
  // Exhaustive search: for every final value up to 2 * max + 2, try all sequences of single and pair raises.
  const memo = new Map();
  const solve = needs => {
    const key = needs.join();
    if (memo.has(key)) return memo.get(key);
    let best = needs.every(v => v === 0) ? 0 : Infinity;
    for (let i = 0; i < needs.length; i++) {
      if (needs[i] === 0 || (i > 0 && needs[i] === needs[i - 1])) continue;
      const one = [...needs];
      one[i]--;
      best = Math.min(best, cost1 + solve(one.sort((a, b) => a - b)));
      for (let j = i + 1; j < needs.length; j++) {
        if (j > i + 1 && needs[j] === needs[j - 1]) continue;
        const two = [...needs];
        two[i]--;
        two[j]--;
        best = Math.min(best, cost2 + solve(two.sort((a, b) => a - b)));
      }
    }
    memo.set(key, best);
    return best;
  };
  const high = Math.max(...nums);
  let best = Infinity;
  for (let target = high; target <= 2 * high + 2; target++) {
    best = Math.min(best, solve(nums.map(v => target - v).sort((a, b) => a - b)));
  }
  return best % 1000000007;
}

