function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 5);
    const top = pick(1, 5);
    const nums = Array.from({ length: n }, () => pick(1, top));
    const cost1 = pick(1, 10);
    const cost2 = rand() < 0.3 ? pick(2 * cost1, 2 * cost1 + 5) : pick(1, 2 * cost1 - 1);
    return [nums, cost1, cost2];
  }
  const n = 2000;
  const shape = rand();
  let nums;
  if (shape < 0.4) nums = Array.from({ length: n }, () => pick(1, 1000000));
  // One element far behind the rest: the target has to rise above the maximum before pairs pay off.
  else if (shape < 0.7) nums = Array.from({ length: n }, (_, i) => (i === 0 ? pick(1, 1000) : pick(999500, 1000000)));
  else nums = Array.from({ length: n }, () => pick(990000, 1000000));
  const cost1 = pick(1, 1000000);
  const cost2 = rand() < 0.2 ? pick(1, 1000000) : pick(1, Math.min(1000000, 2 * cost1 - 1));
  return [nums, cost1, cost2];
}
